public bool Exist(char[][] board, string word)
{
    int rows = board.Length;
    int cols = board[0].Length;

    for (int r = 0; r < rows; r++)
    for (int c = 0; c < cols; c++)
    {
        if (Search(r, c, 0)) return true;
    }

    return false;

    bool Search(int r, int c, int index)
    {
        // Whole word matched
        if (index == word.Length) return true;

        // Out of bounds, wrong character, or already used in this path
        if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
        if (board[r][c] != word[index]) return false;

        char saved = board[r][c];
        board[r][c] = '#';   // mark as visited for this path only

        bool found = Search(r + 1, c, index + 1)
                  || Search(r - 1, c, index + 1)
                  || Search(r, c + 1, index + 1)
                  || Search(r, c - 1, index + 1);

        board[r][c] = saved; // backtrack: make the cell available again
        return found;
    }
}

// Sketch: nodes store the remaining path from the current grid position.
// A trie node holds Children plus a bool IsWord.
private readonly List<string> _found = new();
private readonly System.Text.StringBuilder _path = new();

private void Dfs(int r, int c, int rows, int cols, char[][] board, Trie.Node node)
{
    if (r < 0 || r >= rows || c < 0 || c >= cols) return;

    char ch = board[r][c];
    if (ch == '#' || !node.Children.TryGetValue(ch, out var next)) return;

    _path.Append(ch);
    if (next.IsWord)
    {
        _found.Add(_path.ToString());
        next.IsWord = false; // record once, do not revisit
    }

    board[r][c] = '#';
    Dfs(r + 1, c, rows, cols, board, next);
    Dfs(r - 1, c, rows, cols, board, next);
    Dfs(r, c + 1, rows, cols, board, next);
    Dfs(r, c - 1, rows, cols, board, next);
    board[r][c] = ch;

    _path.Length--;
}

public bool Exist(char[][] board, string word)
{
    int rows = board.Length, cols = board[0].Length;

    for (int r = 0; r < rows; r++)
    for (int c = 0; c < cols; c++)
        if (Search(r, c, 0)) return true;

    return false;

    bool Search(int r, int c, int index)
    {
        if (index == word.Length) return true;
        if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] != word[index]) return false;

        char saved = board[r][c];
        board[r][c] = '#';

        bool found = Search(r + 1, c, index + 1)
                  || Search(r - 1, c, index + 1)
                  || Search(r, c + 1, index + 1)
                  || Search(r, c - 1, index + 1);

        board[r][c] = saved;
        return found;
    }
}
